def photozip(pg,ctx):
    import zipfile
    pg.evaluate("""(async()=>{const c=document.createElement('canvas');c.width=80;c.height=60;c.getContext('2d').fillStyle='#3a7';c.getContext('2d').fillRect(0,0,80,60);const d=c.toDataURL('image/jpeg');
      for(let i=0;i<3;i++){await PhotoDB.put('phz'+i,d);await PhotoDB.put('phz'+i+'_t',d);}
      state.jr.push(jrMigrateEntry({id:'jzip',date:today(),time:'10:00',title:'Zip test',content:'<p>x</p>',photos:['phz0','phz1','phz2']}));persist({now:true});})()"""); pg.wait_for_timeout(1500)
    pg.evaluate("showTab('pgJr');document.getElementById('jrExportBtn').click()"); pg.wait_for_timeout(600)
    t=pg.evaluate("today()"); pg.fill('#jrExpFrom',t); pg.fill('#jrExpTo',t); pg.wait_for_timeout(300)
    cnt=pg.evaluate("document.getElementById('jrExpPhCount').textContent")
    with pg.expect_download(timeout=30000) as dl: pg.click('#jrExpZip')
    d=dl.value; path='/tmp/zz.zip'; d.save_as(path); z=zipfile.ZipFile(path); ok=z.testzip() is None and len(z.namelist())==3
    pg.evaluate("closeSheet()"); return {'ok':ok,'d':cnt+' -> '+d.suggested_filename+' with '+str(len(z.namelist()))+' files'}
def tmenu(pg,ctx):
    pg.evaluate("showTab('pgTasks')"); pg.wait_for_timeout(500); pg.locator('#pgTasks .taskCard').first.locator('.tcMore').click(); pg.wait_for_timeout(300)
    r=pg.evaluate("(()=>{const m=document.querySelector('.tcMenu.on');if(!m)return null;const r=m.getBoundingClientRect(),b=m.closest('.taskCard').querySelector('.tcMore').getBoundingClientRect();return {items:[...m.querySelectorAll('.tcAct')].map(a=>a.innerText.trim()),visible:r.top>=0&&r.bottom<=innerHeight,below:r.top>=b.bottom}})()")
    pg.click('.tcMenu.on [data-task-pin]'); pg.wait_for_timeout(400); pinned=pg.evaluate("state.tasks.some(t=>t.pinned)")
    return {'ok':bool(r) and r['visible'] and r['below'] and pinned and len(r['items'])==3,'d':str(r)+' pinned '+str(pinned)}
